/// `webViewResultUrl#4d22ff98 = WebViewResult`
#[derive(Debug, Clone)]
pub struct WebViewResult {
    pub flags: i32,
    pub fullsize: bool,
    pub fullscreen: bool,
    pub same_origin: bool,
    pub query_id: Option<i64>,
    pub url: String,
}

impl WebViewResult {
    pub fn read_from(r: &mut TLReader) -> Result<Self> {
        let ctor = r.read_u32()?;
        if ctor != WEB_VIEW_RESULT_URL_ID {
            return Err(Error::Serialization(format!(
                "expected webViewResultUrl, got {ctor:#x}"
            )));
        }
    let flags = r.read_i32()?;
    let fullsize = flags & (1 << 1) != 0;
    let fullscreen = flags & (1 << 2) != 0;
    let same_origin = flags & (1 << 3) != 0;
    let query_id = if flags & (1 << 0) != 0 {
        let query_id = r.read_i64()?;
        Some(query_id)
    } else {
        None
    };
    let url = String::from_utf8(r.read_bytes()?)?;
        Ok(WebViewResult {
            flags,
            fullsize,
            fullscreen,
            same_origin,
            query_id,
            url,
        })
    }

    /// Serialize in schema field order (flags auto-computed).
    pub fn write_to(&self, w: &mut crate::serialize::TLWriter) {
    w.write_u32(WEB_VIEW_RESULT_URL_ID);
    let flags: i32 = if self.fullsize { 1 << 1 } else { 0 } | if self.fullscreen { 1 << 2 } else { 0 } | if self.same_origin { 1 << 3 } else { 0 } | if self.query_id.is_some() { 1 << 0 } else { 0 };
    w.write_i32(flags);
    if let Some(query_id) = self.query_id {
        w.write_i64(query_id);
    }
    w.write_bytes(self.url.as_bytes());
    }
}

