/// `auth.exportLoginToken#b7e085fe = auth.LoginToken` — request builder.
/// Returns the serialized method payload (wrap in invoke* at call site).
#[allow(clippy::too_many_arguments)]
pub fn build_auth_export_login_token(
    api_id: i32,
    api_hash: &str,
    except_ids: &[i64]
) -> Vec<u8> {
    let mut w = crate::serialize::TLWriter::new();
    w.write_u32(AUTH_EXPORT_LOGIN_TOKEN_ID);
    w.write_i32(api_id);
    w.write_bytes(api_hash.as_bytes());
    w.write_u32(crate::serialize::VECTOR);
    w.write_i32(except_ids.len() as i32);
    for item in except_ids.iter().copied() {
        w.write_i64(item);
    }
    w.into_bytes()
}

