pub fn build_account_toggle_web_browser_settings_exception(
    delete: bool,
    open_external_browser: Option<bool>,
    url: &str
) -> Vec<u8> {
    let mut w = crate::serialize::TLWriter::new();
    w.write_u32(ACCOUNT_TOGGLE_WEB_BROWSER_SETTINGS_EXCEPTION_ID);
    let flags: i32 = if delete { 1 << 1 } else { 0 } | if open_external_browser.is_some() { 1 << 0 } else { 0 };
    w.write_i32(flags);
    if let Some(open_external_browser) = open_external_browser {
        if open_external_browser { w.write_bool_true(); } else { w.write_bool_false(); }
    }
    w.write_bytes(url.as_bytes());
    w.into_bytes()
}

